from z3 import *

solver = Solver()
N = 3

ordv = [Int(f"ord_{i}") for i in range(N)]
for i in range(N):
    solver.add(ordv[i] >= 0, ordv[i] <= 2)
solver.add(Distinct(ordv))

s = [Int(f"s_{i}") for i in range(N)]

def dur(f):
    return If(f == 0, 15, If(f == 1, 120, 105))

def win_start(f):
    return If(f == 0, -30, If(f == 1, 465, 645))

def win_end(f):
    return If(f == 0, 660, If(f == 1, 780, 780))

def start_travel(f):
    return If(f == 0, 25, If(f == 1, 18, 17))

def travel_between(a, b):
    return If(a == 0,
              If(b == 0, 0, If(b == 1, 7, 11)),
              If(a == 1,
                 If(b == 0, 9, If(b == 1, 0, 7)),
                 If(b == 0, 12, If(b == 1, 7, 0))))

solver.add(s[0] >= start_travel(ordv[0]))
for i in range(N):
    solver.add(s[i] >= win_start(ordv[i]))
    solver.add(s[i] + dur(ordv[i]) <= win_end(ordv[i]))
for i in range(1, N):
    solver.add(s[i] >= s[i-1] + dur(ordv[i-1]) + travel_between(ordv[i-1], ordv[i]))

if solver.check() == sat:
    m = solver.model()
    order = [m.eval(ordv[i], model_completion=True).as_long() for i in range(N)]
    starts = [m.eval(s[i], model_completion=True).as_long() for i in range(N)]
else:
    order = []
    starts = []

def fmt(total):
    total = int(total)
    h = (total // 60) % 24
    mi = total % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{mi:02d}{suffix}"

names = {0: "Melissa", 1: "Emily", 2: "Nancy"}
locations = {0: "Golden Gate Park", 1: "Richmond District", 2: "Presidio"}
duration_map = {0: 15, 1: 120, 2: 105}
travel_from_start = {0: 25, 1: 18, 2: 17}
travel_friend = {
