from z3 import *

def fmt(mins):
    h = mins // 60
    m = mins % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"

loc_names = ["Richmond District", "Sunset District", "Haight-Ashbury", "Mission District", "Golden Gate Park"]
friend_names = ["Sarah", "Richard", "Elizabeth", "Michelle"]
friend_loc = [1, 2, 3, 4]
durations = [30, 90, 120, 90]
avail_start = [645, 705, 660, 1095]
avail_end = [1140, 945, 1035, 1245]
travel_mat = [
    [0, 11, 10, 20, 9],
    [12, 0, 15, 24, 11],
    [10, 15, 0, 11, 7],
    [20, 24, 12, 0, 17],
    [7, 10, 7, 17, 0]
]

opt = Optimize()
k = Int('k')
opt.add(k >= 0, k <= 4)
p = [Int(f'p{i}') for i in range(4)]
s = [Int(f's{i}') for i in range(4)]
e = [Int(f'e{i}') for i in range(4)]

for i in range(4):
    opt.add(p[i] >= -1, p[i] <= 3)
    opt.add(s[i] >= 0, s[i] <= 1440)
    opt.add(e[i] >= 0, e[i] <= 1440)
    opt.add(Implies(i < k, p[i] >= 0))
    opt.add(Implies(i >= k, p[i] == -1))

for i in range(4):
    for j in range(i + 1, 4):
        opt.add(Implies(And(i < k, j < k), p[i] != p[j]))

def loc_of(x):
    return If(x == 0, 1, If(x == 1, 2, If(x == 2, 3, 4)))

def duration_of(x):
    return If(x == 0, 30, If(x == 1, 90, If(x == 2, 120, If(x == 3, 90, 0))))

def avail_start_of(x):
    return If(x == 0, 645, If(x == 1, 705, If(x == 2, 660, If(x == 3, 1095, 0))))

def avail_end_of(x):
    return If(x == 0, 1140, If(x == 1, 945, If(x == 2, 1035, If(x == 3, 1245, 0))))

def travel_time(a, b):
    expr = 0
    for x in range(5):
        for y in range(5):
            expr = If(And(a == x, b == y), travel_mat[x][y], expr)
    return expr

for i in range(4):
    opt.add(Implies(i < k, And(
        s[i] >= avail_start_of(p[i]),
        s[i] + duration_of(p[i]) <= avail_end_of(p[i]),
        e[i] == s[i] + duration_of(p[i])
    )))

opt.add(Implies(k > 0, s[0] >= 540 + travel_time(0, loc_of(p[0]))))
for i in range(1, 4):
    opt.add(Implies(i < k, s[i] >= e[i - 1] + travel_time(loc_of(p[i - 1]), loc_of(p[i]))))

opt.maximize(k)

if opt.check() == sat:
    m = opt.model()
    cnt = m.eval(k).as_long()
    itinerary = [f"You start at Richmond District at {fmt(540)}."]
    current_loc = 0
    current_time = 540
    for i in range(cnt):
        pval = m.eval(p[i]).as_long()
        start = m.eval(s[i]).as_long()
        end = m.eval(e[i]).as_long()
        dest = friend_loc[pval]
        tt = travel_mat[current_loc][dest]
        arrival = current_time + tt
        itinerary.append(f"You travel to {loc_names[dest]} in {tt} minutes and arrive at {fmt(arrival)}.")
        if arrival < start:
            itinerary.append(f"You wait until {fmt(start)}.")
        itinerary.append(f"You meet {friend_names[pval]} for {end - start} minutes from {fmt(start)} to {fmt(end)}.")
        current_loc = dest
        current_time = end
    print(itinerary)
else:
    print([])

